query:
query siteWifiSsid ( $accountId:ID! $wifiSsidRefInput:WifiSsidRefInput!) {
	site ( accountId:$accountId ) {
		wifiSsid ( input:$wifiSsidRefInput  )  {
			id
			networkInterfaceId
			site {
				id
				name
			}
			name
			enabled
			category
			visible
			subnet
			localIp
			dhcp {
				dhcpSubnet
			}
			vlanId
			dhcpEnabled
			microsegmentationEnabled
			internetOnly
			mdnsEnabled
			security {
				mode
				authProtocol
				trackAuthentication
			}
			band
		}
	}	
}
